{
  "application": "ppt-generation",
  "case_id": "case-paper-gpt4o",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 9,
    "audience": "ML researchers, NLP engineers, and graduate students studying large language model architectures",
    "tone": "technical, data-forward, concise"
  },
  "brief": {
    "title": "DeepSeek-V2: Efficient MoE Language Model with Multi-Head Latent Attention",
    "one_liner": "DeepSeek-V2 achieves top-tier open-source LLM performance while activating only 21B of 236B parameters, cutting training costs by 42.5% and KV cache by 93.3% through novel MLA and DeepSeekMoE architectures.",
    "goal": "Understand the architectural innovations (MLA and DeepSeekMoE) that make DeepSeek-V2 both strong and efficient, and appreciate its competitive positioning against leading open-source models."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "DeepSeek-V2: A Strong, Economical, and Efficient MoE Language Model",
      "objective": "Cover slide with model name, key stats (236B total / 21B activated, 128K context), and paper attribution."
    },
    {
      "id": "motivation-and-challenge",
      "title": "The LLM Scaling Dilemma: Performance vs. Training Cost and Inference Speed",
      "objective": "Frame the problem: larger models yield better intelligence but incur prohibitive training costs and slow inference due to KV cache bottlenecks. Set up why MoE + efficient attention is needed."
    },
    {
      "id": "architecture-overview",
      "title": "DeepSeek-V2 Architecture: MLA + DeepSeekMoE in a Transformer Block",
      "objective": "Show the high-level architecture diagram (reference figure_1.jpg) illustrating how MLA replaces standard attention and DeepSeekMoE replaces dense FFN within each Transformer block."
    },
    {
      "id": "mla-mechanism",
      "title": "Multi-Head Latent Attention Compresses KV Cache by 93.3%",
      "objective": "Explain MLA's low-rank key-value joint compression and decoupled RoPE. Use the attention comparison diagram (reference figure_2.jpg) contrasting MHA, GQA, MQA, and MLA to show how MLA achieves better performance with far less cache."
    },
    {
      "id": "deepseek-moe",
      "title": "DeepSeekMoE: Fine-Grained Experts with Shared Expert Isolation",
      "objective": "Describe the MoE architecture with shared and routed experts, top-K routing, device-limited routing for communication efficiency, and auxiliary load-balancing losses. Reference the DeepSeekMoE portion of figure_1.jpg."
    },
    {
      "id": "efficiency-gains",
      "title": "42.5% Training Cost Reduction and 5.76× Generation Throughput vs. DeepSeek 67B",
      "objective": "Present the relative efficiency gains of DeepSeek-V2 over DeepSeek 67B: 42.5% training cost reduction, 93.3% KV cache reduction, and 5.76× higher maximum generation throughput. Use a clear comparison format highlighting these percentage and ratio improvements to emphasize the concrete savings."
    },
    {
      "id": "mmlu-performance-comparison",
      "title": "DeepSeek-V2 Tops MMLU Among Open-Source Models at Only 21B Activated Parameters",
      "objective": "Show the MMLU vs. activated parameters scatter plot (reference figure_3.jpg) positioning DeepSeek-V2 against LLaMA 3 70B, Mixtral 8x22B, Qwen1.5 72B, and others. Highlight the Pareto-optimal position."
    },
    {
      "id": "alignment-results",
      "title": "DeepSeek-V2 Chat (RL) Rivals Closed-Source Models on Chinese Benchmarks",
      "objective": "Summarize alignment pipeline (SFT on 1.5M sessions + GRPO RL) and present chat evaluation scores: AlpacaEval 2.0 (38.9 win rate), MT-Bench (8.97), AlignBench (7.91). Note it outperforms all open-source and most closed-source models in Chinese."
    },
    {
      "id": "takeaways",
      "title": "Key Takeaways: Architectural Innovation Unlocks Efficient Scaling",
      "objective": "Summarize 4-5 key findings: MLA as a superior KV-cache solution, DeepSeekMoE for economical training, top-tier performance at fraction of activated params, strong multilingual alignment, and open-source availability."
    }
  ]
}

