    <script>
        /* ===========================================
           SLIDE PRESENTATION CONTROLLER
           =========================================== */
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.totalSlides = this.slides.length;
                this.progressBar = document.querySelector('.progress-bar');
                this.navDotsContainer = document.querySelector('.nav-dots');

                this.init();
            }

            init() {
                this.setupNavDots();
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupScrollNav();
                this.updateProgress();

                // Mark first slide as visible immediately
                this.slides[0].classList.add('visible');
            }

            setupNavDots() {
                this.slides.forEach((_, index) => {
                    const dot = document.createElement('div');
                    dot.className = 'nav-dot' + (index === 0 ? ' active' : '');
                    dot.addEventListener('click', () => this.goToSlide(index));
                    this.navDotsContainer.appendChild(dot);
                });
            }

            setupIntersectionObserver() {
                const options = {
                    root: null,
                    rootMargin: '0px',
                    threshold: 0.5
                };

                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            const index = Array.from(this.slides).indexOf(entry.target);
                            this.currentSlide = index;
                            this.updateProgress();
                            this.updateNavDots();
                        }
                    });
                }, options);

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown' || e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') {
                        e.preventDefault();
                        this.nextSlide();
                    } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.prevSlide();
                    }
                });
            }

            setupScrollNav() {
                let isScrolling = false;

                document.addEventListener('wheel', (e) => {
                    if (isScrolling) return;

                    isScrolling = true;
                    setTimeout(() => isScrolling = false, 800);
                }, { passive: true });
            }

            goToSlide(index) {
                if (index >= 0 && index < this.totalSlides) {
                    this.slides[index].scrollIntoView({ behavior: 'smooth' });
                }
            }

            nextSlide() {
                if (this.currentSlide < this.totalSlides - 1) {
                    this.goToSlide(this.currentSlide + 1);
                }
            }

            prevSlide() {
                if (this.currentSlide > 0) {
                    this.goToSlide(this.currentSlide - 1);
                }
            }

            updateProgress() {
                const progress = ((this.currentSlide + 1) / this.totalSlides) * 100;
                this.progressBar.style.width = progress + '%';
            }

            updateNavDots() {
                const dots = this.navDotsContainer.querySelectorAll('.nav-dot');
                dots.forEach((dot, index) => {
                    dot.classList.toggle('active', index === this.currentSlide);
                });
            }
        }

        // Initialize presentation
        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
        });
    </script>
